import manifest from "@/data/image-manifest.json";

type ManifestEntry = { widths: number[]; aspect: string | null; width: number; height: number };
const entries = manifest as Record<string, ManifestEntry>;

export interface ResponsiveImage {
  src: string;
  srcSet: string;
  width: number;
  height: number;
}

/**
 * Resolve an image key (e.g. "doctors/dr-kavitha") to the WebP variants generated by
 * scripts/optimize-images.mjs. Width/height are the intrinsic dimensions so the browser
 * can reserve space and avoid layout shift.
 */
export function image(key: string): ResponsiveImage {
  const entry = entries[key];
  if (!entry) throw new Error(`Unknown image key: ${key}`);
  const largest = Math.max(...entry.widths);
  return {
    src: `/assets/${key}-${largest}w.webp`,
    srcSet: entry.widths.map((w) => `/assets/${key}-${w}w.webp ${w}w`).join(", "),
    width: entry.width,
    height: entry.height,
  };
}

export const hasImage = (key: string) => key in entries;
